import { MetricsTimeseriesRevenueDatapoint } from './metrics-timeseries-revenue-datapoint.js';
export class MetricsTimeseriesRevenue {
    currencyCode;
    endsAt;
    interval;
    startsAt;
    timeseries;
    updatedAt;
    constructor(data) {
        this.currencyCode = data.currency_code;
        this.endsAt = data.ends_at;
        this.interval = data.interval;
        this.startsAt = data.starts_at;
        this.timeseries = data.timeseries.map((datapoint) => new MetricsTimeseriesRevenueDatapoint(datapoint));
        this.updatedAt = data.updated_at;
    }
}
